#!/usr/bin/env python3
"""Assembles out/sensitivity_report.md. Every number comes from the data files or the other scripts' JSON (which must carry the same snapshot hash)."""
import json
from datetime import date as Dt
from common import *

det = load_detected(); ref, rinfo = load_refined_info(); T = det["T"]; cands = det["candidates"]
pm = pos(); dates = commit_dates(); series = load_series(dates); SH = snapshot_hash()
events = make_events(ref, pm)
def need(name):
    d = json.load(open(OUT / name))
    if d.get("snapshot_hash") != SH: raise SystemExit(f"{name} was produced from a different input snapshot ({d.get('snapshot_hash')} vs {SH}); run run_all.sh")
    return d
ST, MJ, PJ = need("steps_table.json"), need("mechanisms.json"), need("persistence.json")
rows = {r["sha"]: r for r in ST["events"]}
refmap = {rkey(r): r for r in ref}
n_c = len(cands); done = len({rkey(r) for r in ref if (r["corpus"], r["from_sha"], r["to_sha"]) in {(c["corpus"], c["from_sha"], c["to_sha"]) for c in cands}}); complete = done >= n_c
cls = defaultdict(int)
for r in ref: cls[r["class"]] += 1
ed = lambda sha, fb: dates[sha].strftime("%Y-%m-%d") if sha in dates else fb          # Eastern commit date
cfrom = lambda c: ed(c["from_sha"], c["from_date"]); cto = lambda c: ed(c["to_sha"], c["to_date"])
raw = raw_dcpu
L = [stamp_md(), "**" + (f"COMPLETE: all {n_c} of {n_c} refinements done." if complete else f"PARTIAL: {done} of {n_c} refinements") + "**" +
     f" (pass 1: {rinfo['n_pass1_distinct']} distinct results; pass 2: {rinfo['n_pass2_distinct']}, superseding pass 1. {rinfo['n_changed_class']} result(s) changed class between passes" + (": " + ", ".join(f"{k} x{v}" for k, v in rinfo["change_counts"].items()) if rinfo["change_counts"] else "") + f".) Input snapshot {SH}."]
if not complete: L.append("\nNumbers that depend on refinement (events, buckets, persistence, recall statuses) are provisional and will change.")
L += ["", "# Sensitivity pass: did the sampling of GitGalaxy's history miss important changes?", "",
      "EXPLORATORY. Rules: docs/self_sensitivity_plan.md with Amendments 1 and 2 (Amendment 2 prevails); generated by final/report.py. Items marked POST HOC are additions not declared in the plan. All dates are US Eastern commit dates. Sizes in CPU are never mixed with file-count sizes, which are marked (files).", ""]

# ---- 1 recall
L += ["## 1. Recall of the known events", "", "A candidate counts for a known event only if it brackets (or, for the two interval events, overlaps) it, has the expected direction, and exceeds T on the CPU metric (raw, unrounded). Expected directions: E1 up, E2 down (the file screen removed vendored trees), E3 up, earlier step up, drift up. Status order: LOCALISED, UNCONFIRMED (all matching refinements finished and none localised it), FLAGGED (flagged, refinement pending or localised another commit), MISSED.", "",
      "| known event | matching candidates (corpus, raw dCPU) | status | detail |", "|---|---|---|---|"]
def status(matches, loc_ok):
    rs = [refmap.get(key_(c)) for c in matches]
    if any(loc_ok(r) for r in rs if r): return "LOCALISED"
    if not matches: return "MISSED"
    if all(r is not None for r in rs): return "UNCONFIRMED" if any(r["class"] in ("UNCONFIRMED", "UNEVALUABLE") for r in rs) else "FLAGGED"
    return "FLAGGED"
key_ = lambda c: (c["corpus"], c["from_sha"], c["to_sha"])
def detail(matches):
    return "; ".join(f"{c['corpus']} {raw(c):+.1%}: " + (f"{refmap[key_(c)]['class']} (pass {refmap[key_(c)]['_pass']}) at {str(refmap[key_(c)].get('found'))[:10]}" if key_(c) in refmap else "not yet refined") for c in matches) or "no matching candidate"
KN = [("E1 #3929", "6b604f91a731a1c7a257db8ffb29f350f370fefb", False), ("E2 #5512", "14fc9c7a55cd5d980e3008e586195046057b97c2", True), ("E3 #1234", "89d86da58ad7e69bdc6827c6f8999985e8903185", False)]
for name, sha, down in KN:
    k = pm[sha]
    m = [c for c in cands if c["from"] < k <= c["to"] and abs(raw(c)) > T[c["corpus"]] and (raw(c) < 0) == down]
    ok = lambda r: r["class"] == "LOCALISED" and r.get("found") == sha and r.get("metric", "cpu_s") == "cpu_s" and r["down"] == down
    L.append(f"| {name} (idx {k}, {ed(sha, '')}) | {', '.join(f'{c['corpus']} {raw(c):+.1%}' for c in m) or 'none'} | {status(m, ok)} | {detail(m)} |")
E3 = pm[KN[2][1]]
def interval(name, lo, hi, extra=lambda c: True):
    m = [c for c in cands if c["corpus"] == "language-crucible" and cfrom(c) <= hi and cto(c) >= lo and raw(c) > T[c["corpus"]] and extra(c)]
    ramps = [r for r in det["ramps"] if r["corpus"] == "language-crucible" and r["cumulative"] > 0 and ed("", r["from_date"]) <= hi and r["to_date"] >= lo]
    def ok(r): return r["class"] == "LOCALISED" and r.get("metric", "cpu_s") == "cpu_s" and not r["down"] and r.get("found") in dates and lo <= dates[r["found"]].strftime("%Y-%m-%d") <= hi
    s = status(m, ok)
    if s == "MISSED" and ramps: s = "FLAGGED"
    L.append(f"| {name} | {', '.join(f'{c['corpus']} idx {c['from']}-{c['to']} ({cfrom(c)}..{cto(c)}, {c['cpu'][0]:.1f}->{c['cpu'][1]:.1f} s, {raw(c):+.1%})' for c in m) or 'none'}{'; ramp ' + ', '.join(f'{r['cumulative']:+.0%}' for r in ramps) if ramps else ''} | {s} | {detail(m)} |")
interval("earlier step 2026-07-27..08-13 (language-crucible, before E3)", "2026-07-27", "2026-08-13", lambda c: c["from"] < E3)
interval("drift 2026-11-04..11-20 (language-crucible)", "2026-11-04", "2026-11-20")
L.append("")

# ---- 2 events
L += ["## 2. Localised steps (events)", "", f"{len(events)} events from {cls['LOCALISED']} LOCALISED refinements (passes merged; deduped by commit and by (corpus, commit); CPU preferred over files). Details: steps_table.md / .csv.", "",
      "| date | idx | commit | known | direction | CPU size | files size (files) | corpora | bucket | files by kind (core/std/tools/tests/docs/other) | subject |", "|---|---|---|---|---|---|---|---|---|---|---|"]
inv = {sha: n for n, sha, _ in KN}
for e in events:
    r = rows[e["sha"]]
    L.append(f"| {r['date'][:10]} | {r['index']} | {r['commit']} | {inv.get(e['sha'], '')} | {r['direction']} | {pct(e['size_cpu']) if e['size_cpu'] is not None else 'n/a'} | {pct(e['size_files']) + ' (files)' if e['size_files'] is not None else 'n/a'} | {r['corpora']} | {r['bucket']} | " + "/".join(str(r['files_' + k]) for k in KINDS) + f" | {r['subject'][:70]} |")
L.append("")

# ---- 3 counts
unres = det["unresolved_failed_commits"]; ud = {u["index"] for u in unres}
L += ["## 3. Counts", "", f"- Candidates (detector): {n_c} (" + ", ".join(f"{t} {sum(1 for c in cands if c['corpus'] == t)}" for t in CORPORA) + ")",
      f"- Refined: {done}; LOCALISED {cls['LOCALISED']}, UNCONFIRMED {cls['UNCONFIRMED']}, UNEVALUABLE {cls['UNEVALUABLE']}; not yet refined {n_c - done}",
      f"- Distinct events (commits): {len(events)}; ramps: {len(det['ramps'])}",
      f"- Engine crash: {len(unres)} failed timed runs on {len(ud)} distinct commits: " + ", ".join(f"{t} {sum(1 for u in unres if u['corpus'] == t)}" for t in CORPORA), ""]
gp = [g for t in CORPORA for g in crash_gap_pairs(series, t)]
candk = {(c["corpus"], c["from"], c["to"]) for c in cands}
L += [f"### UNRESOLVED pairs (consecutive timed commits spanning a failed run), {len(gp)} pairs", "", "The detector bridges such pairs; their change cannot be attributed to one commit. A pair above T or 3% files may hide a step or crash cost.", "",
      "| corpus | idx | dates | CPU s | dCPU | dFiles | above T or 3% files | detector candidate | failed idx |", "|---|---|---|---|---|---|---|---|---|"]
for g in gp:
    big = abs(g["dcpu"]) > T[g["corpus"]] or (g["dfiles"] is not None and abs(g["dfiles"]) > 0.03)
    L.append(f"| {g['corpus']} | {g['from']}-{g['to']} | {g['from_date']}..{g['to_date']} | {g['cpu'][0]:.2f}->{g['cpu'][1]:.2f} | {g['dcpu']:+.1%} | {'n/a' if g['dfiles'] is None else format(g['dfiles'], '+.1%')} | {'yes' if big else 'no'} | {'yes' if (g['corpus'], g['from'], g['to']) in candk else 'no'} | {','.join(map(str, g['failed_indices']))} |")
if not gp: L.append("| none | | | | | | | | |")
L += ["", "Engine crash commits (date, index, sha): " + "; ".join(f"{d} {i} {s[:10]}" for i, d, s in sorted({(u['index'], u['date'], u['sha']) for u in unres})) + ".", ""]

# ---- 4 floor
L += ["## 4. Detection floor (A/A noise)", "", "T = max(10%, 4 x largest relative deviation of the corpus's A/A anchor runs from their median). A step smaller than T (or than 3% in files mapped) cannot be flagged by a single pair.", "",
      "| corpus | A/A runs | T | timed points | median CPU s | T in CPU s at the median |", "|---|---|---|---|---|---|"]
for t in CORPORA:
    tmv = timed(series, t); med = st.median(s["cpu"] for _, s in tmv) if tmv else None
    L.append(f"| {t} | {det['anchor_runs'].get(t)} | {T[t]:.1%} | {len(tmv)} | {num(med,1)} | {num(T[t]*med if med else None,1)} |")
ab = [c for c in cands if abs(c["cpu"][1] - c["cpu"][0]) >= 0.5]
evab = [(e, c) for e in events for c in e["corpora"].values() if c["metric"] == "cpu_s" and abs(c["boundary"][1] - c["boundary"][0]) >= 0.5]
nev = sum(1 for e in events for c in e["corpora"].values() if c["metric"] == "cpu_s")
L += ["", f"POST HOC (Amendment 2 iv): absolute floor of 0.5 CPU seconds. Candidates with |change| >= 0.5 s: {len(ab)} of {n_c} (" + ", ".join(f"{t} {sum(1 for c in ab if c['corpus'] == t)}/{sum(1 for c in cands if c['corpus'] == t)}" for t in CORPORA) + f"); CPU-metric event (corpus, commit) boundaries with |change| >= 0.5 s: {len(evab)} of {nev}.", ""]

# ---- 5 months etc
L += ["## 5. Events by month and corpus, step sizes, single-corpus steps", ""]
months = sorted({dates[e["sha"]].strftime("%Y-%m") for e in events})
L += ["| month | events | " + " | ".join(CORPORA) + " |", "|---|---|" + "---|" * len(CORPORA)]
for m in months:
    es = [e for e in events if dates[e["sha"]].strftime("%Y-%m") == m]
    L.append(f"| {m} | {len(es)} | " + " | ".join(str(sum(1 for e in es if c in e["corpora"])) for c in CORPORA) + " |")
sizes = sorted(abs(c["boundary_rel"]) for e in events for c in e["corpora"].values() if c["metric"] == "cpu_s")
if sizes:
    qs = lambda q: sizes[min(len(sizes) - 1, int(q * len(sizes)))]
    L += ["", f"CPU step-size distribution (|boundary_rel|, CPU-metric (corpus, step) pairs, n={len(sizes)}): min {sizes[0]:.0%}, median {st.median(sizes):.0%}, 75th pct {qs(.75):.0%}, max {sizes[-1]:.0%}; above 25%: {sum(1 for x in sizes if x > .25)}, above 50%: {sum(1 for x in sizes if x > .5)}, above 100%: {sum(1 for x in sizes if x > 1)}. Histogram: figures/step_size_hist.png. File-count (files) sizes are in section 2."]
else: L += ["", "No CPU-metric steps yet."]
one = [e for e in events if len(e["corpora"]) == 1]
L += ["", f"Events seen by only one corpus: {len(one)} of {len(events)}: " + "; ".join(f"{rows[e['sha']]['date'][:10]} {e['sha'][:10]} ({next(iter(e['corpora']))})" for e in one) + ".", "",
      "POST HOC: events by direction: " + ", ".join(f"{d} {sum(1 for e in events if e['direction'] == d)}" for d in ("up", "down", "mixed")) + ".", ""]

# ---- 6 mechanisms / persistence
L += ["## 6. Mechanisms, persistence (details in mechanisms.md, persistence.md)", ""]
L.append("- Bucket counts, events: " + ", ".join(f"({b}) {n}" for b, n in MJ["bucket_counts_events"].items()) + f"; engine-path commits {MJ['n_engine_path_commits']} ({MJ['n_cache_gap_commits']} cache-gap core commits excluded from the test): " + ", ".join(f"({b}) {n}" for b, n in MJ["bucket_counts_engine_path"].items()))
for gname, d in MJ["quiet_tests"].items():
    v = d["variants"]["q_ab3"]
    L.append(f"- Quiet test, {gname}: {v['quiet_events']}/{v['n_events']} = {pct(v['share'])} (95% {pct(v['ci95'][0])} to {pct(v['ci95'][1])}) vs {v['quiet_others']}/{v['n_others']} = {pct(v['share_others'],1)} of the other engine-path commits; Fisher p = {num(v['fisher_p'],4)}, era-stratified Mantel-Haenszel p = {num(v['mh_p'],4)} (OR {num(v['mh_odds_ratio'],2)}). Cutoff 5: {pct(d['variants']['q_ab5']['share'])}, p = {num(d['variants']['q_ab5']['fisher_p'],4)}; strict (a): {d['variants']['q_strict_a']['quiet_events']}/{d['variants']['q_strict_a']['n_events']}.")
t = MJ["text_screen"]["corrected_regex"]; o = MJ["text_screen"]["join_steps_regex_old"]
L.append(f"- Text screen (corrected regex; engine-path commits): recall {t['events_hit']}/{t['events_in_population']}, precision {pct(t['precision'],1)} (lower bound; events missed by sampling count against it), hit rate {pct(t['hit_rate'],1)}. Inherited join_steps regex: recall {o['events_hit']}/{o['events_in_population']}, precision {pct(o['precision'],1)}, hit rate {pct(o['hit_rate'],1)}.")
S = PJ["summary"]; pp = S["pooled_corpus_commit_pairs"]
L.append(f"- Persistence (evaluable, non-overlapping UP steps; {S['n_overlapping_excluded']} overlapping excluded; {len(PJ['not_evaluated'])} not evaluated): " + (f"{pp['n']} (corpus, commit) steps, {pp['n_reversed']} reversed ({pct(pp['share_reversed'])}), {pp['n_elevated_at_tip']} elevated at the tip ({pct(pp['share_elevated_at_tip'])}); per commit: {S['pooled_per_commit']['n_commits']} commits, reversed in all {S['pooled_per_commit']['all_corpora_reversed']}, none {S['pooled_per_commit']['none_reversed']}, mixed {S['pooled_per_commit']['mixed']}." if pp.get("n") else "none evaluable yet."))
L.append(f"- DOWN steps (CPU): {len(PJ['down_steps'])}.")
L.append("")

# ---- 7 cannot see
L += ["## 7. What the sample cannot see", ""]
N = len(head_list())
for t in CORPORA:
    idx = [i for i, _ in timed(series, t)]; gaps = [b - a for a, b in zip(idx, idx[1:])]
    if len(idx) < 2: L.append(f"- {t}: {len(idx)} timed point(s); no gaps to report."); continue
    g = max(gaps); L.append(f"- {t}: {len(idx)} of {N} first-parent commits timed ({len(idx)/N:.1%}); median gap {st.median(gaps):.0f} commits, largest gap {g} commits (idx {idx[gaps.index(g)]}-{idx[gaps.index(g)+1]}).")
L += ["- A change and its reversal inside one sampling gap leaves no trace; two opposite steps in one pair can cancel below T.",
      f"- Steps smaller than T (section 4) and slow ramps under 2T per 10 timed commits are invisible; ramps found: {len(det['ramps'])}.",
      "- Only CPU seconds and files mapped enter the rule: wall-only, memory and output-content effects are not measured.",
      "- Only four corpora (three small, one large): steps that need other languages or large inputs to show cannot be seen.",
      f"- Crash gaps (section 3): {len(gp)} timed pairs span a failed run; the cost across them is unknown.",
      "- Refinement bisects with one threshold at the midpoint; several steps in one pair are reported as one, or as UNCONFIRMED. Events are selected for being large, then compared with all commits, and commits in a series (one feature over several PRs) are not independent."]
L += ["", "## Figures", "", "- figures/cpu_series.png, figures/step_size_hist.png, figures/events_per_month.png, figures/known_events.png", ""]
(OUT / "sensitivity_report.md").write_text("\n".join(L) + "\n")
print("report: " + ("COMPLETE" if complete else f"PARTIAL {done} of {n_c}"))
